    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs().powi(2);

    let horizon_factor = (step_index as f64 / total_jobs as f64).powi(3);

    let lookahead_factor = if next_job_cpu == job_cpu && next_job_ram == job_ram {
        0.5
    } else {
        1.0
    };

    let score = cpu_norm + ram_norm - imbalance_penalty * horizon_factor * lookahead_factor;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let horizon_factor = step_index as f64 / total_jobs as f64;

    // Lookahead awareness for the next two jobs
    let lookahead_cpu = next_job_cpu * 2; // Assuming the next job is the same as the current one for simplicity
    let lookahead_ram = next_job_ram * 2;
    let can_fit_next_job = node_residual_cpu >= lookahead_cpu && node_residual_ram >= lookahead_ram;

    let mut score = cpu_norm + ram_norm - imbalance_penalty * horizon_factor;
    if can_fit_next_job {
        // Pairing complementary jobs is more beneficial
        score -= 0.5; // Penalize pairing to avoid resource wastage
    }

    // Non-linear conditional for lookahead bonus
    if step_index < total_jobs / 2 {
        score += (node_residual_cpu * node_residual_ram) as f64 * 0.1; // Bonus for fitting jobs early
    } else {
        score -= (node_residual_cpu * node_residual_ram) as f64 * 0.1; // Penalty for fitting jobs late
    }

    // Imbalance penalty adjustment based on horizon
    if imbalance_penalty > 0.5 {
        score -= imbalance_penalty * horizon_factor; // Increase penalty as imbalance increases with time
    }

    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Penalties for resource imbalance and stranding
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let next_job_fit_penalty = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram { 0.0 } else { 1.0 };

    // Reward for fitting the job
    let fit_reward = 1.0 / ((node_residual_cpu + job_cpu) as f64 / node_capacity_cpu as f64 * (node_residual_ram + job_ram) as f64 / node_capacity_ram as f64);

    let score = cpu_norm + ram_norm - imbalance_penalty - next_job_fit_penalty + fit_reward;
    score
}
